test_snippets.java:
public static void check(Solution solution) {
    assert Arrays.equals(solution.canTransform("XXL", "LXX"), True);
    assert Arrays.equals(solution.canTransform("RXXLRXRXL", "XRLXXRRLX"), True);
    assert Arrays.equals(solution.canTransform("LLR", "RRL"), False);
    assert Arrays.equals(solution.canTransform("RXXL", "XRXL"), True);
    assert Arrays.equals(solution.canTransform("XRXL", "LXXR"), False);
    assert Arrays.equals(solution.canTransform("RL", "LR"), False);
    assert Arrays.equals(solution.canTransform("RLX", "LXR"), False);
    assert Arrays.equals(solution.canTransform("XXXXXLXXXX", "LXXXXXXXXX"), True);
    assert Arrays.equals(solution.canTransform("XXRXXLXXXX", "XXXXRXXLXX"), False);
    assert Arrays.equals(solution.canTransform("XXLXXRXXX", "XXXLXXRXX"), False);
    assert Arrays.equals(solution.canTransform("RLXXXRRLL", "RXXRLXXLR"), False);
    assert Arrays.equals(solution.canTransform("XXXX", "XXXX"), True);
    assert Arrays.equals(solution.canTransform("LXXR", "XRXL"), False);
